struct Container {
    data: String,
}

fn take_data(container: Container) -> String {
    container.data
}

fn main() {
    let mut container = Container { data: "Hello".to_string() };
    let original_len = container.data.len();

    let moved_data = take_data(container);

    assert_eq!(original_len, 5);
    assert_eq!(moved_data, "Hello");

    println!("Ownership verified");
}
